using System.Text.Json.Nodes;
namespace MyProjectManagement;
public static class Workforce {
 public static readonly string[] Flags=["manageCustomers","manageWeeklyPlans","rescheduleAllocations","manageClientHours","viewAmcCompliance"];
 public static bool Default(string role,string flag)=>Flags.Contains(flag)&&(role=="Project manager"||role=="Project lead"&&flag is "manageWeeklyPlans" or "rescheduleAllocations" or "viewAmcCompliance");
 public static void Customers(JsonArray next,JsonArray old){var rows=next.OfType<JsonObject>().ToList();J.Require(rows.Count==next.Count&&rows.Count<=5000,"Invalid customer catalog",400);J.Require(rows.Select(r=>J.S(r,"id")).Distinct().Count()==rows.Count&&rows.Select(r=>J.S(r,"code").ToUpperInvariant()).Distinct().Count()==rows.Count,"Customer IDs and codes must be unique",400);foreach(var r in rows)J.Require(System.Text.RegularExpressions.Regex.IsMatch(J.S(r,"id"),"^[A-Za-z0-9_-]{1,100}$")&&J.S(r,"code")==J.S(r,"code").Trim()&&J.S(r,"code").Length is >0 and <=50&&J.S(r,"name").Trim().Length is >0 and <=160&&r["active"] is JsonValue b&&b.TryGetValue<bool>(out _),"Enter customer code (50 max), name (160 max) and status",400);foreach(var r in old.OfType<JsonObject>())J.Require(rows.Any(n=>J.S(n,"id")==J.S(r,"id")),"Deactivate customers instead of deleting them",400);}
 public static void Project(Snapshot state,JsonObject row,JsonObject? old){var id=J.S(row,"customerId");if(old is not null&&id==J.S(old,"customerId"))return;J.Require(J.A(state.Settings,"customers").Any(c=>J.S(c,"id")==id&&J.B(c,"active",true)),"Select an active customer from Customer master",400);}
 public static bool HasActual(JsonObject a)=>Amc.Hours(a,true)>0;
 public static bool BillingOnly(JsonObject row,JsonObject old){if(!JsonNode.DeepEquals(J.Without(row,["allocations"]),J.Without(old,["allocations"])))return false;var previous=J.A(old,"allocations").ToDictionary(a=>J.S(a,"id"));var current=J.A(row,"allocations").ToList();string[] billing=["billableToClient","billingConfirmed","billingUpdatedBy","billingUpdatedAt","billingHistory"];return current.Count==previous.Count&&current.All(a=>previous.TryGetValue(J.S(a,"id"),out var p)&&JsonNode.DeepEquals(J.Without(a,billing),J.Without(p,billing)));}
 public static void Schedule(JsonObject a,JsonObject? old,Policy policy,string pid){if(old is null)return;var fields=new[]{"date","plannedHours","plannedStartTime","plannedEndTime","plannedBreakMinutes"};if(fields.Any(k=>!JsonNode.DeepEquals(a[k],old[k])))J.Require(policy.Flag("rescheduleAllocations")&&policy.ProjectScope(pid)&&(J.S(a,"assignee")==policy.Actor||policy.Flag("assignTasks")),"Rescheduling permission required");}
 public static void Billing(JsonObject a,JsonObject? old,Policy policy,string pid){bool changed=old is null?!J.B(a,"billableToClient",true)||J.B(a,"billingConfirmed"):J.B(a,"billableToClient",true)!=J.B(old,"billableToClient",true)||J.B(a,"billingConfirmed")!=J.B(old,"billingConfirmed")||!JsonNode.DeepEquals(a["billingHistory"],old["billingHistory"])||J.S(a,"billingUpdatedBy")!=J.S(old,"billingUpdatedBy")||J.S(a,"billingUpdatedAt")!=J.S(old,"billingUpdatedAt");
 if(changed&&!(old is null&&policy.Owner)){J.Require(policy.Flag("manageClientHours")&&policy.ProjectScope(pid)||policy.Flag("updateTasks")&&J.S(a,"assignee")==policy.Actor,"Client-hour deduction permission required");J.Require(J.S(a,"billingUpdatedBy")==policy.Actor,"Billing audit identity required");J.Require(J.ContainsAll(a["billingHistory"],old?["billingHistory"]),"Billing history cannot be rewritten");var added=J.A(a,"billingHistory").Skip(J.A(old,"billingHistory").Count()).ToList();J.Require(added.Count>0&&added.All(h=>J.S(h,"by")==policy.Actor)&&J.B(added.Last(),"deduct",true)==J.B(a,"billableToClient",true),"Append the current updater and deduction choice to billing history");}
 if(J.S(a,"teamGroupId")!=""&&HasActual(a))J.Require(a["billableToClient"] is JsonValue v&&v.TryGetValue<bool>(out _)&&J.B(a,"billingConfirmed"),"Confirm Yes or No for client-hour deduction on this team session",400);
 }
 public static void Aggregate(JsonObject t){var rows=J.A(t,"allocations").ToList();if(rows.Count>1&&J.S(t,"status")=="Completed"&&rows.Any(a=>J.S(a,"status")!="Completed")){t["status"]="In progress";t["completion"]=(int)Math.Round(rows.Count(a=>J.S(a,"status")=="Completed")*100m/rows.Count);t["actualFinish"]="";}}
 public static void SyncCalendar(Snapshot state){var expected=new HashSet<string>();foreach(var (key,t) in state.Records.Where(x=>x.Key.StartsWith("task:")).ToList())foreach(var a in J.A(t,"allocations")){bool untimed=a["plannedHours"] is not null;if(!untimed&&(!TimeOnly.TryParseExact(J.S(a,"plannedStartTime"),"HH:mm",out _)||!TimeOnly.TryParseExact(J.S(a,"plannedEndTime"),"HH:mm",out _)))continue;string id="cal-"+J.S(a,"id"),record="meeting:"+id;expected.Add(record);state.Records[record]=new JsonObject{["id"]=id,["calendarSource"]="daily-allocation",["parentTaskId"]=J.S(t,"id"),["parentAllocationId"]=J.S(a,"id"),["project"]=J.S(t,"project"),["companyId"]=J.S(t,"companyId"),["module"]=J.S(t,"module"),["assignee"]=J.S(a,"assignee"),["title"]="Allocated · "+J.S(t,"title"),["date"]=J.S(a,"date"),["hoursOnly"]=untimed,["allDay"]=untimed,["time"]=untimed?"00:00":J.S(a,"plannedStartTime"),["duration"]=untimed?(int)(Amc.Hours(a,false)*60):J.Minute(J.S(a,"plannedEndTime"))-J.Minute(J.S(a,"plannedStartTime")),["type"]="Daily allocation",["location"]=J.S(a,"workMode"),["notes"]=J.S(a,"instructions")};}
 foreach(var key in state.Records.Where(x=>x.Key.StartsWith("meeting:")&&J.S(x.Value,"calendarSource")=="daily-allocation"&&!expected.Contains(x.Key)).Select(x=>x.Key).ToList())state.Records.Remove(key);
 }
}
